    const esc=s=>String(s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

    function opXml(op,W){
    if(op.kind==='lb'){
      LEG.l++;OPID++;
      const flip=op.flip, y=flip?+(W-op.y).toFixed(3):op.y;
      return `        <OperationLineBore Quan="${op.quan}" Ang="0" Diameter="${op.dia}" Quan_Eq="${op.quan}" Ang_Eq="" Diameter_Eq="${op.dia}" ID="${OPID}" X="${op.x}" Y="${y}" Depth="${op.depth}" Hide="False" X_Eq="${op.x}" Y_Eq="${y}" Depth_Eq="${op.depth}" Hide_Eq="" IsUserOp="True" Noneditable="False" Anchor="" FlipSideOp="${flip?'True':'False'}">\r\n          <OpIdTag TypeCode="0" LegacyNumber="${LEG.l}" />\r\n        </OperationLineBore>\r\n`;
    }
    LEG.h++;OPID++;
    let extra='',x=op.x,y=op.y,flip=op.flip;
    if(op.mode==='edge'){
      flip=false;
      const ang={X0:0,XL:180,Y0:90,YW:270}[op.edge];
      if(op.edge==='X0')x=0; if(op.edge==='XL')x=op.partL;
      if(op.edge==='Y0')y=0; if(op.edge==='YW')y=W;
      extra=` HBoreAngle="${ang}" HBoreDepth="${op.hdepth}" Dowel="True"`;
    } else if(flip){ y=+(W-y).toFixed(3); }
    return `        <OperationHole Diameter="${op.dia}" Diameter_Eq="${op.dia}" ID="${OPID}" X="${x}" Y="${y}" Depth="${op.depth}" Hide="False" X_Eq="${x}" Y_Eq="${y}" Depth_Eq="${op.depth}" Hide_Eq="" IsUserOp="True" Noneditable="False" Anchor="" FlipSideOp="${flip?'True':'False'}"${extra}>\r\n          <OpIdTag TypeCode="0" LegacyNumber="${LEG.h}" />\r\n        </OperationHole>\r\n`;
  }

    function partXml(p){
    // v3.45 — Zac: "why would the SRE change ANY parts at all!? it should
    // ONLY be changing the 'cabinet' they're assigned to." Correct, and the
    // house rule agrees: carry the specimen, never reconstruct. When the
    // importer captured the part's verbatim source text, emit it untouched
    // except the ONE thing the SRE owns — the layer Comment. The synthesizer
    // below survives only for text-imported recipes with no .moz source.
    if (p.raw) {
      MAN++;
      let raw = p.raw;
      if (/\bComment="/.test(raw)) raw = raw.replace(/(<CabProdPart\b[^>]*?Comment=")[^"]*(")/, `$1${p.layer}$2`);
      return '    ' + raw + '\r\n';
    }
    MAN++;
    const eb=[p.bands.F,p.bands.E,p.bands.B,p.bands.S].map(b=>b?1:0);
    const pts=[[0,0,1],[p.L,0,2],[p.L,p.W,3],[0,p.W,4]];
    const sp=pts.map((q,i)=>`        <ShapePoint ID="${i}" X="${q[0]}" Y="${q[1]}" PtType="0" Data="0" EdgeType="${q[2]}" Anchor="" EBand="${eb[i]}" X_Eq="" Y_Eq="" Data_Eq="" LAdj="0" RAdj="0" TAdj="0" BAdj="0" Scribe="0" Source="0" BoreHoles="0" EBandLock="False" SideName="" />\r\n`).join('');
    const ops=p.ops.map(o=>opXml({...o,partL:p.L},p.W)).join('');
    const opsX=ops?`      <PartOpsXml Version="2">\r\n${ops}      </PartOpsXml>\r\n`:`      <PartOpsXml Version="2" />\r\n`;
    const P=p.pos;
    return `    <CabProdPart Name="${esc(p.name)}" ReportName="${esc(p.report)}" UsageType="0" HighDetail="True" Comment="${esc(p.layer)}" CommentLocked="True" Quan="${p.qty}" W="${p.W}" L="${p.L}" Color="" ColorLocked="False" Type="${p.type}" Q_EQ="" W_EQ="" L_EQ="" Layer="1" X="${P.X}" Y="${P.Y}" Z="${P.Z}" X_EQ="" Y_EQ="" Z_EQ="" A1="${P.A1}" A2="${P.A2}" A3="${P.A3}" R1="X" R2="Y" R3="Z" Face="0" A1_EQ="" A2_EQ="" A3_EQ="" Radius="0" RadAxis="0" SUPartName="" SUPartD="0">\r\n      <PartShapeXml Version="2" Name="" Type="1" RadiusX="0" RadiusY="0" Source="1" Data1="0" Data2="0" RotAng="0" DoNotTranslateTo00="False">\r\n${sp}      </PartShapeXml>\r\n${opsX}      <PartTag SourceCode="0" TypeCode="-1" IsAddedByCustomParm="False" IsModifiedByCustomParm="False">\r\n        <PartTagReference Key="Manual" Value="${MAN}" />\r\n      </PartTag>\r\n    </CabProdPart>\r\n`;
  }

